import { request_directory_access } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
// import { update_audit_logs } from "@/mixins/AuditLogActions.js";

export default {
  props: {
    requestAccessDialog: Boolean,
    rowInfo: Object
  },
  // mixins: [update_audit_logs],
  data() {
    return {
      loading: false
    };
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    async request_access() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(request_directory_access, {
          input: {
            directory_id: this.rowInfo.directory_id,
            organization_id: data.organization.organization_id,
            user_email_id: data.user.user_email_id
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.request_directory_access);
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    },
    async fetch_audit_message() {
      var data = this.$store.getters.GetUserObj;
      var data = {
        AuditType: "DIRECTORY_ACTION",
        AuditAction: "DELETE_DIRECTORY",
        AuditMessage: `${data.user.full_user_name} Dleted   ${this.rowInfo.directory_name} Directory`
      };
      this.$store.commit("SetAuditActions", data);
      // this.update_audit_logs();
    }
  }
};
